var e=[{title:`Hur komplex en övning är`,text:`En stödd maskinrodd rör sig längs en stabil bana. En rumänsk marklyft på ett ben kräver balans, bålkontroll och höftkoordination, och en kettlebellsving lägger till fart och timing. Du kan vara mycket stark och ändå vara ny på en av dessa färdigheter.`},{title:`Gå från förutsägbart till utmanande`,text:`Börja med stabila positioner och långsammare repetitioner och lär dig en ny färdighet i taget. Gör sedan övningen svårare genom att ta bort stöd, ändra hävarm, öka rörelseomfånget eller lägga till kontrollerad fart. En progression bör behålla rörelsens syfte och undvika att ändra alla krav på en gång.`},{title:`Trötthet ändrar koordinationen`,text:`En övning du gjorde bra tidigt i ett pass kan bli ostadig efter många repetitioner. Gör övningar med hög färdighet tidigare, vila längre när du behöver och avsluta ett set när balansen eller kontrollen glider. Komplexa ballistiska övningar är oftast ett dåligt första val för en trött nybörjare.`},{title:`Exempel`,text:`Om du lär dig utfall kan du börja med split-knäböj medan du håller i ett räcke, gå vidare till baklänges utfall utan stöd och prova gående utfall senare. En snabbare variant är inte automatiskt bättre.`},{title:`Så använder du TrainUp`,text:`När TrainUp bygger ditt program väljer det övningar som passar din nivå och koordination såväl som dina begränsningar och din utrustning.`}];var r=[{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACSM 2026: praktisk vägledning`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var a={sections:e,sources:r};export{a as default,e as sections,r as sources};